14	#include "kmu.h"
15	
16	using namespace vortex;
17	
18	Kmu::Kmu(const SimContext& ctx, const char* name)
19	  : SimObject<Kmu>(ctx, name)
20	  , PC_(0)
21	  , entry_(0)
22	  , param_(0)
23	  , lmem_size_(0)
24	  , block_size_(0)
25	  , running_(false)
26	  , cta_id_(0)
27	{
28	  block_dim_[0]    = block_dim_[1]    = block_dim_[2]    = 1;
29	  grid_dim_[0]     = grid_dim_[1]     = grid_dim_[2]     = 1;
30	  cluster_dim_[0]  = cluster_dim_[1]  = cluster_dim_[2]  = 1;
31	  warp_step_[0]    = warp_step_[1]    = warp_step_[2]    = 1;
32	  group_origin_[0] = group_origin_[1] = group_origin_[2] = 0;
33	  intra_offset_[0] = intra_offset_[1] = intra_offset_[2] = 0;
34	}
35	
36	void Kmu::on_reset() {
37	  // Reset only the per-run progression state. The kernel descriptor (PC,
38	  // param, dims, block_size, lmem_size, warp_step, cluster_dim) is set
39	  // by dcr_write() before run() and must persist across
40	  // SimPlatform::on_reset().
41	  running_         = false;
42	  cta_id_          = 0;
43	  group_origin_[0] = group_origin_[1] = group_origin_[2] = 0;
44	  intra_offset_[0] = intra_offset_[1] = intra_offset_[2] = 0;
45	}
46	
47	void Kmu::dcr_write(uint32_t addr, uint32_t value) {
48	  switch (addr) {
49	  case VX_DCR_KMU_STARTUP_ADDR0: PC_    = (PC_    & ~uint64_t(0xFFFFFFFF)) | value; break;
50	  case VX_DCR_KMU_STARTUP_ADDR1: PC_    = (PC_    &  uint64_t(0xFFFFFFFF)) | (uint64_t(value) << 32); break;
51	  case VX_DCR_KMU_KERNEL_ENTRY0: entry_ = (entry_ & ~uint64_t(0xFFFFFFFF)) | value; break;
52	  case VX_DCR_KMU_KERNEL_ENTRY1: entry_ = (entry_ &  uint64_t(0xFFFFFFFF)) | (uint64_t(value) << 32); break;
53	  case VX_DCR_KMU_STARTUP_ARG0:  param_ = (param_ & ~uint64_t(0xFFFFFFFF)) | value; break;
54	  case VX_DCR_KMU_STARTUP_ARG1:  param_ = (param_ &  uint64_t(0xFFFFFFFF)) | (uint64_t(value) << 32); break;
55	  case VX_DCR_KMU_BLOCK_DIM_X:   block_dim_[0] = value; break;
56	  case VX_DCR_KMU_BLOCK_DIM_Y:   block_dim_[1] = value; break;
57	  case VX_DCR_KMU_BLOCK_DIM_Z:   block_dim_[2] = value; break;
58	  case VX_DCR_KMU_GRID_DIM_X:    grid_dim_[0]  = value; break;
59	  case VX_DCR_KMU_GRID_DIM_Y:    grid_dim_[1]  = value; break;
60	  case VX_DCR_KMU_GRID_DIM_Z:    grid_dim_[2]  = value; break;
61	  case VX_DCR_KMU_LMEM_SIZE:     lmem_size_    = value; break;
62	  case VX_DCR_KMU_BLOCK_SIZE:    block_size_   = value; break;
63	  case VX_DCR_KMU_WARP_STEP_X:   warp_step_[0] = value; break;
64	  case VX_DCR_KMU_WARP_STEP_Y:   warp_step_[1] = value; break;
65	  case VX_DCR_KMU_WARP_STEP_Z:   warp_step_[2] = value; break;
66	  case VX_DCR_KMU_CLUSTER_DIM_X: cluster_dim_[0] = value; break;
67	  case VX_DCR_KMU_CLUSTER_DIM_Y: cluster_dim_[1] = value; break;
68	  case VX_DCR_KMU_CLUSTER_DIM_Z: cluster_dim_[2] = value; break;
69	  default: break;
70	  }
71	}
72	
73	void Kmu::start() {
74	  running_ = (block_size_ > 0)
75	           && (grid_dim_[0] > 0)
76	           && (grid_dim_[1] > 0)
77	           && (grid_dim_[2] > 0)
78	           && (cluster_dim_[0] > 0)
79	           && (cluster_dim_[1] > 0)
80	           && (cluster_dim_[2] > 0);
81	  if (running_) {
82	    cta_id_          = 0;
83	    group_origin_[0] = group_origin_[1] = group_origin_[2] = 0;
84	    intra_offset_[0] = intra_offset_[1] = intra_offset_[2] = 0;
85	  }
86	}
87	
88	bool Kmu::step(kmu_req_t* req) {
89	  if (!running_) return false;
90	
91	  // Effective block_idx = group_origin + intra_offset.
92	  uint32_t block_idx[3] = {
93	    group_origin_[0] + intra_offset_[0],
94	    group_origin_[1] + intra_offset_[1],
95	    group_origin_[2] + intra_offset_[2],
96	  };
97	
98	  req->PC           = PC_;
99	  req->entry        = entry_;
100	  req->param        = param_;
101	  req->cta_id       = cta_id_;
102	  req->block_idx[0] = block_idx[0];
103	  req->block_idx[1] = block_idx[1];
104	  req->block_idx[2] = block_idx[2];
105	  req->block_dim[0] = block_dim_[0];
106	  req->block_dim[1] = block_dim_[1];
107	  req->block_dim[2] = block_dim_[2];
108	  req->grid_dim[0]  = grid_dim_[0];
109	  req->grid_dim[1]  = grid_dim_[1];
110	  req->grid_dim[2]  = grid_dim_[2];
111	  req->lmem_size    = lmem_size_;
112	  req->block_size   = block_size_;
113	  req->warp_step[0] = warp_step_[0];
114	  req->warp_step[1] = warp_step_[1];
115	  req->warp_step[2] = warp_step_[2];
116	  req->cluster_dim[0] = cluster_dim_[0];
117	  req->cluster_dim[1] = cluster_dim_[1];
118	  req->cluster_dim[2] = cluster_dim_[2];
119	  req->is_first_of_cluster = (intra_offset_[0] == 0)
120	                          && (intra_offset_[1] == 0)
121	                          && (intra_offset_[2] == 0);
122	
123	  // Advance the intra-cluster offset first (fills the cluster), then the
124	  // group_origin in (X, Y, Z) order when the inner loop wraps.
125	  ++cta_id_;
126	  bool intra_x_wrap = (intra_offset_[0] + 1 == cluster_dim_[0]);
127	  if (!intra_x_wrap) {
128	    intra_offset_[0]++;
129	  } else {
130	    intra_offset_[0] = 0;
131	    bool intra_y_wrap = (intra_offset_[1] + 1 == cluster_dim_[1]);
132	    if (!intra_y_wrap) {
133	      intra_offset_[1]++;
134	    } else {
135	      intra_offset_[1] = 0;
136	      bool intra_z_wrap = (intra_offset_[2] + 1 == cluster_dim_[2]);
137	      if (!intra_z_wrap) {
138	        intra_offset_[2]++;
139	      } else {
140	        intra_offset_[2] = 0;
141	        // Cluster complete — advance group_origin in (X, Y, Z) order.
142	        uint32_t ox = group_origin_[0] + cluster_dim_[0];
143	        if (ox == grid_dim_[0]) {
144	          group_origin_[0] = 0;
145	          uint32_t oy = group_origin_[1] + cluster_dim_[1];
146	          if (oy == grid_dim_[1]) {
147	            group_origin_[1] = 0;
148	            uint32_t oz = group_origin_[2] + cluster_dim_[2];
149	            if (oz == grid_dim_[2]) {
150	              group_origin_[2] = 0;
151	              running_ = false;
152	            } else {
153	              group_origin_[2] = oz;
154	            }
155	          } else {
156	            group_origin_[1] = oy;
157	          }
158	        } else {
159	          group_origin_[0] = ox;
160	        }
161	      }
162	    }
163	  }
164	
165	  return true;
166	}
