13	namespace vortex {
14	
15	// ============================================================================
16	// Static GPU capability words
17	//
18	// GPU_DEV_CAPS / GPU_ISA_CAPS register values exposed as read-only MMIO.
19	// sw/runtime/common/vx_caps.h is the matching decoder.
20	// ============================================================================
21	namespace {
22	constexpr unsigned cp_clog2(uint64_t n) {
23	    unsigned r = 0;
24	    while ((uint64_t(1) << r) < n) ++r;
25	    return r;
26	}
27	uint64_t gpu_dev_caps() {
28	    const unsigned cluster_size = VX_CFG_NUM_CORES / VX_CFG_SOCKET_SIZE;
29	    const unsigned bank_addr_w  = VX_CFG_PLATFORM_MEMORY_ADDR_WIDTH
30	                                - cp_clog2(VX_CFG_PLATFORM_MEMORY_NUM_BANKS);
31	    return  (uint64_t(VX_ISA_IMPL_ID) & 0xFF)
32	         | ((uint64_t(cp_clog2(VX_CFG_NUM_THREADS))  & 0x7)  << 8)
33	         | ((uint64_t(cp_clog2(VX_CFG_NUM_WARPS))    & 0x7)  << 11)
34	         | ((uint64_t(cp_clog2(VX_CFG_SOCKET_SIZE))  & 0x7)  << 14)
35	         | ((uint64_t(cp_clog2(cluster_size))        & 0x7)  << 17)
36	         | ((uint64_t(cp_clog2(VX_CFG_NUM_CLUSTERS)) & 0x7)  << 20)
37	         | ((uint64_t(cp_clog2(VX_CFG_ISSUE_WIDTH))  & 0x7)  << 23)
38	         | ((uint64_t(VX_CFG_LMEM_ENABLED ? VX_CFG_LMEM_LOG_SIZE : 0) & 0xFF) << 26)
39	         | ((uint64_t(cp_clog2(VX_CFG_PLATFORM_MEMORY_NUM_BANKS)) & 0x7) << 34)
40	         | ((uint64_t(bank_addr_w - 20) & 0x1F) << 37);
41	}
42	uint64_t gpu_isa_caps() {
43	    return  (uint64_t(VX_CFG_MISA_EXT) << 32)
44	         | ((uint64_t(cp_clog2(VX_CFG_XLEN) - 4) & 0x3) << 30)
45	         |  uint64_t(VX_CFG_MISA_STD);
46	}
47	} // namespace
48	
49	CommandProcessor::CommandProcessor(const Hooks& hooks)
50	    : hooks_(hooks) {}
51	
52	bool CommandProcessor::enabled() const {
53	    return (cp_ctrl_ & 0x1) && (q0_.control & 0x1);
54	}
55	
56	bool CommandProcessor::busy() const {
57	    return enabled() && (q0_.head < q0_.tail
58	                         || cl_loaded_
59	                         || eng_state_ != EngState::Idle
60	                         || launch_state_ != LaunchState::Idle);
61	}
62	
63	// ============================================================================
64	// MMIO surface
65	// ============================================================================
66	
67	void CommandProcessor::mmio_write(uint32_t off, uint32_t value) {
68	    // Globals
69	    switch (off) {
70	        case 0x000: cp_ctrl_ = value; return;
71	        // CP_SATP — page-table root for the CP DMA's MMU.
72	        case 0x028: satp_ = (satp_ & 0xFFFFFFFF00000000ULL) |  uint64_t(value);         return;
73	        case 0x02C: satp_ = (satp_ & 0x00000000FFFFFFFFULL) | (uint64_t(value) << 32);  return;
74	        // STATUS / DEV_CAPS / CYCLE / GPU caps are RO; ignore writes.
75	        case 0x004: case 0x008: case 0x010: case 0x014:
76	        case 0x018: case 0x01C: case 0x020: case 0x024: return;
77	    }
78	    // Queue 0 (offsets 0x100..0x12F)
79	    if (off >= 0x100 && off < 0x140) {
80	        switch (off - 0x100) {
81	            case 0x00: q0_.ring_base   = (q0_.ring_base & 0xFFFFFFFF00000000ULL) | uint64_t(value);            return;
82	            case 0x04: q0_.ring_base   = (q0_.ring_base & 0x00000000FFFFFFFFULL) | (uint64_t(value) << 32);   return;
83	            case 0x08: q0_.head_addr   = (q0_.head_addr & 0xFFFFFFFF00000000ULL) | uint64_t(value);           return;
84	            case 0x0C: q0_.head_addr   = (q0_.head_addr & 0x00000000FFFFFFFFULL) | (uint64_t(value) << 32);   return;
85	            case 0x10: q0_.cmpl_addr   = (q0_.cmpl_addr & 0xFFFFFFFF00000000ULL) | uint64_t(value);           return;
86	            case 0x14: q0_.cmpl_addr   = (q0_.cmpl_addr & 0x00000000FFFFFFFFULL) | (uint64_t(value) << 32);   return;
87	            case 0x18: q0_.ring_log2   = uint8_t(value & 0xFF);                                                 return;
88	            case 0x1C: q0_.control     = value;                                                                 return;
89	            case 0x20: q0_.tail_lo_staging = value;                                                             return;
90	            case 0x24: {
91	                // Atomic tail commit: writing the HI word completes the 64-bit update.
92	                q0_.tail = (uint64_t(value) << 32) | uint64_t(q0_.tail_lo_staging);
93	                return;
94	            }
95	            // SEQNUM / ERROR are RO; ignore.
96	            case 0x28: case 0x2C: return;
97	        }
98	    }
99	    // Unknown offset — silently ignored.
100	}
101	
102	uint32_t CommandProcessor::mmio_read(uint32_t off) const {
103	    switch (off) {
104	        case 0x000: return cp_ctrl_;
105	        case 0x004: return uint32_t(busy() ? 1 : 0);    // CP_STATUS bit0
106	        case 0x008: {
107	            // CP_DEV_CAPS: {SUPPORTS_QMD:1 @bit26 | SUPPORTS_DRAW:1 @bit25 |
108	            // VM_ENABLED:1 @bit24 | AXI_TID_W:8 | RING_LOG2:8 | NUM_QUEUES:8}.
109	            // Defaults: TID=6, RING_LOG2=16, NUM_QUEUES=1. VM_ENABLED reflects
110	            // the build-config so the config-agnostic libvortex.so can
111	            // discover VM at open. SUPPORTS_DRAW / SUPPORTS_QMD = 1: this
112	            // (Emulation) CP decodes CMD_DRAW (OP_DRAW) and CMD_LAUNCH_QMD;
113	            // the RTL CP advertises 0 until its mirrors are synth-validated,
114	            // so the runtime falls back to plain ring commands there.
115	            uint32_t vm_enabled = 0;
116	#ifdef VX_CFG_VM_ENABLE
117	            vm_enabled = 1u << 24;
118	#endif
119	            const uint32_t supports_draw = 1u << 25;
120	            const uint32_t supports_qmd  = 1u << 26;
121	            return supports_qmd | supports_draw | vm_enabled
122	                 | (uint32_t(6) << 16) | (uint32_t(16) << 8) | uint32_t(1);
123	        }
124	        case 0x010: return uint32_t(cycle_counter_ & 0xFFFFFFFF);
125	        case 0x014: return uint32_t(cycle_counter_ >> 32);
126	        case 0x018: return uint32_t(gpu_dev_caps() & 0xFFFFFFFF);
127	        case 0x01C: return uint32_t(gpu_dev_caps() >> 32);
128	        case 0x020: return uint32_t(gpu_isa_caps() & 0xFFFFFFFF);
129	        case 0x024: return uint32_t(gpu_isa_caps() >> 32);
130	        case 0x028: return uint32_t(satp_ & 0xFFFFFFFF);
131	        case 0x02C: return uint32_t(satp_ >> 32);
132	    }
133	    if (off >= 0x100 && off < 0x140) {
134	        switch (off - 0x100) {
135	            case 0x00: return uint32_t(q0_.ring_base & 0xFFFFFFFF);
136	            case 0x04: return uint32_t(q0_.ring_base >> 32);
137	            case 0x08: return uint32_t(q0_.head_addr & 0xFFFFFFFF);
138	            case 0x0C: return uint32_t(q0_.head_addr >> 32);
139	            case 0x10: return uint32_t(q0_.cmpl_addr & 0xFFFFFFFF);
140	            case 0x14: return uint32_t(q0_.cmpl_addr >> 32);
141	            case 0x18: return uint32_t(q0_.ring_log2);
142	            case 0x1C: return q0_.control;
143	            case 0x20: return q0_.tail_lo_staging;
144	            case 0x24: return uint32_t(q0_.tail >> 32);
145	            case 0x28: return uint32_t(q0_.seqnum & 0xFFFFFFFF);
146	            case 0x2C: return q0_.error;
147	            case 0x30: return last_dcr_rsp_;  // last CMD_DCR_READ response
148	        }
149	    }
150	    return 0xDEADBEEF;
151	}
152	
153	// ============================================================================
154	// VM — page-table walk (the CP DMA is an MMU-aware copy engine)
155	// ============================================================================
156	
157	uint64_t CommandProcessor::cp_translate(uint64_t vaddr, bool physical) const {
158	#ifdef VX_CFG_VM_ENABLE
159	    if (physical || satp_ == 0)
160	        return vaddr;
161	    SATP_t satp(satp_);
162	    if (satp.get_mode() == BARE)
163	        return vaddr;
164	    // Sv32/Sv39 walk — mirrors VMManager::page_table_walk so the CP DMA and
165	    // the host driver resolve addresses identically.
166	    int i = VX_VM_PT_LEVEL - 1;
167	    vAddr_t va(vaddr);
168	    uint64_t cur_base_ppn = satp.get_base_ppn();
169	    for (;;) {
170	        uint64_t pte_addr  = cur_base_ppn * VX_VM_PT_SIZE
171	                           + va.vpn[i] * VX_VM_PTE_SIZE;
172	        uint64_t pte_bytes = 0;
173	        if (hooks_.dram_read)
174	            hooks_.dram_read(pte_addr, &pte_bytes, VX_VM_PTE_SIZE);
175	        PTE_t pte(pte_bytes);
176	        if (pte.v == 0)
177	            return vaddr;            // unmapped — pass through (defensive)
178	        if (pte.r == 0 && pte.w == 0 && pte.x == 0) {
179	            if (--i < 0)
180	                return vaddr;        // no leaf — pass through
181	            cur_base_ppn = pte.ppn;
182	            continue;
183	        }
184	        cur_base_ppn = pte.ppn;      // leaf found at level i
185	        break;
186	    }
187	    // Reconstruct the physical address. For a leaf found at level i > 0 (a
188	    // mega/gigapage) the low VX_VM_PAGE_LOG2_SIZE + i*VPN_BITS address bits
189	    // are the offset *within* the superpage and must come from the VA, not
190	    // from the (superpage-aligned) leaf PPN. For a 4 KB leaf (i == 0) this
191	    // reduces to the ordinary ppn<<12 | page-offset.
192	    constexpr unsigned VPN_BITS = cp_clog2(VX_VM_PT_SIZE / VX_VM_PTE_SIZE);
193	    const uint64_t off_mask =
194	        (uint64_t(1) << (VX_VM_PAGE_LOG2_SIZE + i * VPN_BITS)) - 1;
195	    return ((cur_base_ppn << VX_VM_PAGE_LOG2_SIZE) & ~off_mask)
196	         | (vaddr & off_mask);
197	#else
198	    (void)physical;
199	    return vaddr;
200	#endif
201	}
202	
203	// ============================================================================
204	// Fetch + unpack
205	// ============================================================================
206	
207	void CommandProcessor::fetch_if_needed() {
208	    if (cl_loaded_) return;
209	    if (q0_.head >= q0_.tail) return;
210	    const uint64_t mask = (uint64_t(1) << q0_.ring_log2) - 1;
211	    const uint64_t off  = q0_.head & mask;
212	    if (!hooks_.dram_read) return;
213	    hooks_.dram_read(q0_.ring_base + off, cl_buf_.data(), CL_BYTES);
214	    cl_loaded_   = true;
215	    cl_cmd_slot_ = 0;
216	    unpack_cl();
217	}
218	
219	int CommandProcessor::decode_cmd(int off, Cmd& out) {
220	    return decode_cmd_bytes(cl_buf_.data(), int(CL_BYTES), off, out);
221	}
222	
223	int CommandProcessor::decode_cmd_bytes(const uint8_t* buf, int len,
224	                                       int off, Cmd& out) {
225	    auto rd8 = [&](int o) -> uint8_t {
226	        return (o >= 0 && o < len) ? buf[o] : 0;
227	    };
228	    auto rd64 = [&](int o) -> uint64_t {
229	        uint64_t v = 0;
230	        for (int i = 0; i < 8; ++i)
231	            v |= uint64_t(rd8(o + i)) << (8 * i);
232	        return v;
233	    };
234	    out.opcode   = rd8(off + 0);
235	    out.flags    = rd8(off + 1);
236	    out.reserved = uint16_t(rd8(off + 2)) | (uint16_t(rd8(off + 3)) << 8);
237	    out.arg0     = rd64(off + 4);
238	    out.arg1     = rd64(off + 12);
239	    out.arg2     = rd64(off + 20);
240	    // Command size in bytes by opcode.
241	    switch (out.opcode) {
242	        case OP_NOP:        return 4;
243	        case OP_LAUNCH:     return 12;
244	        case OP_LAUNCH_QMD: return 12;   // arg0 = QMD descriptor address
245	        case OP_DRAW:       return 12;   // arg0 = draw descriptor address
246	        case OP_FENCE:      return 8;
247	        case OP_CACHE_FLUSH: return 12;
248	        case OP_DCR_WRITE:  return 20;
249	        case OP_DCR_READ:   return 20;
250	        case OP_EVENT_SIG:  return 20;
251	        case OP_EVENT_WAIT: return 28;
252	        case OP_MEM_WRITE:
253	        case OP_MEM_READ:
254	        case OP_MEM_COPY:   return 28;
255	        default:            return 4;
256	    }
257	}
258	
259	void CommandProcessor::unpack_cl() {
260	    cl_cmd_count_ = 0;
261	    cl_cmd_slot_  = 0;
262	    int offset = 0;
263	    for (int slot = 0; slot < MAX_CMDS_PER_CL; ++slot) {
264	        if (offset + 4 > int(CL_BYTES)) break;
265	        const uint8_t opcode = cl_buf_[offset];
266	        const uint8_t flags  = cl_buf_[offset + 1];
267	        // Zero header = padding sentinel; stop.
268	        if (opcode == 0 && flags == 0) break;
269	        Cmd c;
270	        const int sz = decode_cmd(offset, c);
271	        if (offset + sz > int(CL_BYTES)) break;
272	        ++cl_cmd_count_;
273	        offset += sz;
274	    }
275	}
276	
277	// ============================================================================
278	// Engine FSM
279	// ============================================================================
280	
281	void CommandProcessor::publish_completion() {
282	    if (!hooks_.dram_write || q0_.cmpl_addr == 0) return;
283	    uint64_t seq = q0_.seqnum;
284	    hooks_.dram_write(q0_.cmpl_addr, &seq, sizeof(seq));
285	}
286	
287	// wait_op_e encoded in arg2[1:0].
288	bool CommandProcessor::event_wait_satisfied_() {
289	    if (!hooks_.dram_read) return true;   // no DRAM hook -> retire as NOP
290	    uint64_t cur = 0;
291	    hooks_.dram_read(cur_cmd_.arg0, &cur, sizeof(cur));
292	    const uint64_t target = cur_cmd_.arg1;
293	    const uint32_t op = uint32_t(cur_cmd_.arg2) & 0x3;
294	    switch (op) {
295	        case 0: return cur == target;   // WAIT_OP_EQ
296	        case 1: return cur >= target;   // WAIT_OP_GE
297	        case 2: return cur >  target;   // WAIT_OP_GT
298	        case 3: return cur != target;   // WAIT_OP_NE
299	        default: return true;
300	    }
301	}
302	
303	// CMD_LAUNCH_QMD: read the KMU descriptor from device memory and replay it
304	// through the DCR-write hook. The descriptor is a {uint32 count, then count ×
305	// (uint32 dcr_addr, uint32 value)} list the host staged before submit (like a
306	// kernel-args blob). cp_translate matches the address the host's CMD_MEM_WRITE
307	// staged it at (VM walk when active, passthrough otherwise).
308	void CommandProcessor::apply_qmd_(uint64_t qmd_addr) {
309	    if (!hooks_.dram_read || !hooks_.vortex_dcr_write) return;
310	    uint64_t addr = cp_translate(qmd_addr, /*physical=*/false);
311	    uint32_t count = 0;
312	    hooks_.dram_read(addr, &count, sizeof(count));
313	    addr += sizeof(count);
314	    constexpr uint32_t MAX_QMD_DCRS = 64;   // backstop against a corrupt count
315	    if (count > MAX_QMD_DCRS) count = MAX_QMD_DCRS;
316	    for (uint32_t i = 0; i < count; ++i) {
317	        uint32_t pair[2] = {0, 0};          // {dcr_addr, value}
318	        hooks_.dram_read(addr, pair, sizeof(pair));
319	        addr += sizeof(pair);
320	        hooks_.vortex_dcr_write(pair[0] & 0xFFF, pair[1]);  // VX_DCR_ADDR_BITS=12
321	    }
322	}
323	
324	// Execute one draw-bundle step. Inline ops (DCR_WRITE/DCR_READ/CACHE_FLUSH)
325	// complete immediately and return false; a launch step (LAUNCH/LAUNCH_QMD)
326	// kicks the launch sub-FSM and returns true so the caller waits for the drain
327	// (the inter-stage barrier). Mirrors the per-opcode logic of the ring Bid path.
328	bool CommandProcessor::exec_inline_cmd_(const Cmd& c) {
329	    switch (c.opcode) {
330	        case OP_LAUNCH:
331	        case OP_LAUNCH_QMD:
332	            if (c.opcode == OP_LAUNCH_QMD)
333	                apply_qmd_(c.arg0);
334	            launch_state_ = LaunchState::PulseStart;
335	            return true;
336	        case OP_DCR_WRITE:
337	            if (hooks_.vortex_dcr_write)
338	                hooks_.vortex_dcr_write(uint32_t(c.arg0 & 0xFFF),
339	                                        uint32_t(c.arg1 & 0xFFFFFFFF));
340	            return false;
341	        case OP_DCR_READ:
342	            if (hooks_.vortex_dcr_read)
343	                last_dcr_rsp_ = hooks_.vortex_dcr_read(
344	                    uint32_t(c.arg0 & 0xFFF), uint32_t(c.arg1 & 0xFFFFFFFF));
345	            return false;
346	        case OP_CACHE_FLUSH:
347	            if (hooks_.vortex_dcr_read) {
348	                uint32_t n = uint32_t(c.arg0 & 0xFFFFFFFF);
349	                for (uint32_t cid = 0; cid < n; ++cid)
350	                    (void)hooks_.vortex_dcr_read(VX_DCR_BASE_CACHE_FLUSH, cid);
351	            }
352	            return false;
353	        default:
354	            // NOP / FENCE / unknown step — no-op (draws don't use MEM_*/EVENT_*).
355	            return false;
356	    }
357	}
358	
359	// Read draw_step_'s 28-byte cmd record from the descriptor into draw_cmd_.
360	void CommandProcessor::draw_load_step_() {
361	    draw_cmd_ = Cmd{};
362	    if (!hooks_.dram_read) return;
363	    uint8_t buf[DRAW_STEP_BYTES] = {0};
364	    const uint64_t at = draw_phys_ + 4
365	                      + uint64_t(draw_step_) * DRAW_STEP_BYTES;
366	    hooks_.dram_read(at, buf, DRAW_STEP_BYTES);
367	    decode_cmd_bytes(buf, DRAW_STEP_BYTES, 0, draw_cmd_);
368	}
369	
370	void CommandProcessor::tick_launch() {
371	    switch (launch_state_) {
372	        case LaunchState::Idle:        return;
373	        case LaunchState::PulseStart:
374	            if (hooks_.vortex_start) hooks_.vortex_start();
375	            launch_state_ = LaunchState::WaitBusy;
376	            return;
377	        case LaunchState::WaitBusy:
378	            // Wait for Vortex to actually start.
379	            if (hooks_.vortex_busy && hooks_.vortex_busy())
380	                launch_state_ = LaunchState::WaitDrain;
381	            return;
382	        case LaunchState::WaitDrain:
383	            if (!hooks_.vortex_busy || !hooks_.vortex_busy())
384	                launch_state_ = LaunchState::Idle;
385	            return;
386	    }
387	}
388	
389	void CommandProcessor::tick_engine() {
390	    // Decode a single cmd at the current slot and walk it through the FSM.
391	    auto load_next_cmd = [this]() -> bool {
392	        if (!cl_loaded_) return false;
393	        if (cl_cmd_slot_ >= cl_cmd_count_) {
394	            // All commands in this CL consumed (or it was pure padding);
395	            // advance head and drop the CL.
396	            q0_.head   += CL_BYTES;
397	            cl_loaded_ = false;
398	            return false;
399	        }
400	        int off = 0;
401	        for (int s = 0; s < cl_cmd_slot_; ++s) {
402	            Cmd skip;
403	            off += decode_cmd(off, skip);
404	        }
405	        decode_cmd(off, cur_cmd_);
406	        cur_is_launch_ = (cur_cmd_.opcode == OP_LAUNCH ||
407	                          cur_cmd_.opcode == OP_LAUNCH_QMD);
408	        switch (cur_cmd_.opcode) {
409	            case OP_NOP: case OP_FENCE:
410	                // No resource bid for these opcodes; retire as NOP.
411	                cur_is_no_resource_ = true;
412	                break;
413	            default:
414	                // LAUNCH, DCR_*, MEM_*, EVENT_SIG, EVENT_WAIT all bid a
415	                // resource.
416	                cur_is_no_resource_ = false;
417	                break;
418	        }
419	        return true;
420	    };
421	
422	    switch (eng_state_) {
423	        case EngState::Idle:
424	            fetch_if_needed();
425	            if (load_next_cmd())
426	                eng_state_ = EngState::Decode;
427	            return;
428	
429	        case EngState::Decode:
430	            if (cur_is_no_resource_) {
431	                eng_state_ = EngState::Retire;
432	            } else {
433	                eng_state_ = EngState::Bid;
434	            }
435	            return;
436	
437	        case EngState::Bid:
438	            // Dispatch to the resource. Single-queue means we always win
439	            // the arbiter, so transition immediately to WaitDone.
440	            if (cur_is_launch_) {
441	                // QMD launch: the KMU descriptor lives in memory as a
442	                // {count, (dcr_addr,value)...} list (NVIDIA QMD model). Apply
443	                // it through the DCR-write hook, then pulse start exactly like
444	                // a plain CMD_LAUNCH — collapsing ~18 ring DCR writes to one.
445	                if (cur_cmd_.opcode == OP_LAUNCH_QMD)
446	                    apply_qmd_(cur_cmd_.arg0);
447	                launch_state_ = LaunchState::PulseStart;
448	                eng_state_    = EngState::WaitDone;
449	            } else if (cur_cmd_.opcode == OP_DRAW) {
450	                // Device-orchestrated draw: arg0 → resident draw descriptor
451	                // {uint32 num_steps, steps[28 B]...}. Walk the embedded command
452	                // bundle (DrawStep), retiring the one OP_DRAW when drained.
453	                draw_phys_ = cp_translate(cur_cmd_.arg0, /*physical=*/false);
454	                draw_num_steps_ = 0;
455	                if (hooks_.dram_read)
456	                    hooks_.dram_read(draw_phys_, &draw_num_steps_,
457	                                     sizeof(draw_num_steps_));
458	                if (draw_num_steps_ > MAX_DRAW_STEPS)
459	                    draw_num_steps_ = MAX_DRAW_STEPS;
460	                draw_step_ = 0;
461	                eng_state_ = EngState::DrawStep;
462	            } else if (cur_cmd_.opcode == OP_DCR_WRITE) {
463	                // Issue the DCR write through the hook and retire immediately.
464	                if (hooks_.vortex_dcr_write) {
465	                    uint32_t addr = uint32_t(cur_cmd_.arg0 & 0xFFF); // VX_DCR_ADDR_BITS=12
466	                    uint32_t val  = uint32_t(cur_cmd_.arg1 & 0xFFFFFFFF);
467	                    hooks_.vortex_dcr_write(addr, val);
468	                }
469	                eng_state_ = EngState::Retire;
470	            } else if (cur_cmd_.opcode == OP_DCR_READ) {
471	                // Issue the DCR read; latch the response into the regfile
472	                // slot so the host can grab it after polling Q_SEQNUM.
473	                if (hooks_.vortex_dcr_read) {
474	                    uint32_t addr = uint32_t(cur_cmd_.arg0 & 0xFFF);
475	                    uint32_t tag  = uint32_t(cur_cmd_.arg1 & 0xFFFFFFFF);
476	                    last_dcr_rsp_ = hooks_.vortex_dcr_read(addr, tag);
477	                }
478	                eng_state_ = EngState::Retire;
479	            } else if (cur_cmd_.opcode == OP_CACHE_FLUSH) {
480	                // Sweep a per-core DCR-read of VX_DCR_BASE_CACHE_FLUSH across
481	                // [0, num_cores). arg0 carries num_cores; dcr_read routes each
482	                // call to flush_caches() (drains dcache/L2/L3 to memsim).
483	                if (hooks_.vortex_dcr_read) {
484	                    uint32_t n = uint32_t(cur_cmd_.arg0 & 0xFFFFFFFF);
485	                    for (uint32_t cid = 0; cid < n; ++cid) {
486	                        (void)hooks_.vortex_dcr_read(VX_DCR_BASE_CACHE_FLUSH, cid);
487	                    }
488	                }
489	                eng_state_ = EngState::Retire;
490	            } else if (cur_cmd_.opcode == OP_EVENT_SIG) {
491	                // CMD_EVENT_SIGNAL: write arg1 (8-byte value) to arg0
492	                // (device counter slot).
493	                if (hooks_.dram_write) {
494	                    uint64_t v = cur_cmd_.arg1;
495	                    hooks_.dram_write(cur_cmd_.arg0, &v, sizeof(v));
496	                }
497	                eng_state_ = EngState::Retire;
498	            } else if (cur_cmd_.opcode == OP_EVENT_WAIT) {
499	                // CMD_EVENT_WAIT: poll arg0 until it satisfies the wait_op
500	                // (arg2[1:0]) comparison against arg1; retry each tick.
501	                if (event_wait_satisfied_()) {
502	                    eng_state_ = EngState::Retire;
503	                } else {
504	                    // Spin in Bid (no state change); re-checked each tick.
505	                }
506	            } else if (cur_cmd_.opcode == OP_MEM_WRITE ||
507	                       cur_cmd_.opcode == OP_MEM_READ  ||
508	                       cur_cmd_.opcode == OP_MEM_COPY) {
509	                // CMD_MEM_*: copy arg2 bytes from src (arg1) to dst (arg0).
510	                // The CP DMA is an MMU-aware copy engine: the device-side
511	                // operand is a virtual address, translated here by a
512	                // page-table walk. MEM_WRITE -> arg0 is the device dst;
513	                // MEM_READ -> arg1 is the device src; MEM_COPY -> both.
514	                // Host-side operands and physical-flagged commands pass
515	                // through untranslated. A buffer is one contiguous PA
516	                // allocation, so translating the base covers the transfer.
517	                if (hooks_.dram_read && hooks_.dram_write
518	                 && cur_cmd_.arg2 != 0) {
519	                    const bool physical =
520	                        (cur_cmd_.flags & MEM_FLAG_PHYSICAL) != 0;
521	                    uint64_t dst = cur_cmd_.arg0;
522	                    uint64_t src = cur_cmd_.arg1;
523	                    if (cur_cmd_.opcode == OP_MEM_WRITE) {
524	                        dst = cp_translate(dst, physical);
525	                    } else if (cur_cmd_.opcode == OP_MEM_READ) {
526	                        src = cp_translate(src, physical);
527	                    } else { // OP_MEM_COPY — both operands are device
528	                        dst = cp_translate(dst, physical);
529	                        src = cp_translate(src, physical);
530	                    }
531	                    const uint64_t total = cur_cmd_.arg2;
532	                    constexpr uint64_t CHUNK = 64 * 1024;
533	                    std::vector<uint8_t> buf(
534	                        std::size_t(total < CHUNK ? total : CHUNK));
535	                    for (uint64_t done = 0; done < total; ) {
536	                        uint64_t n = total - done;
537	                        if (n > CHUNK) n = CHUNK;
538	                        hooks_.dram_read (src + done, buf.data(), n);
539	                        hooks_.dram_write(dst + done, buf.data(), n);
540	                        done += n;
541	                    }
542	                }
543	                eng_state_ = EngState::Retire;
544	            } else {
545	                // Unknown opcode — retire as NOP.
546	                eng_state_ = EngState::Retire;
547	            }
548	            return;
549	
550	        case EngState::WaitDone:
551	            // For LAUNCH: wait until the launch FSM is back in Idle.
552	            if (cur_is_launch_ && launch_state_ != LaunchState::Idle)
553	                return;
554	            eng_state_ = EngState::Retire;
555	            return;
556	
557	        case EngState::DrawStep:
558	            // Walk the draw descriptor one step per tick. Inline ops apply now;
559	            // a launch step transitions to DrawLaunchWait until its kernel
560	            // drains (the inter-stage barrier).
561	            if (draw_step_ >= draw_num_steps_) {
562	                eng_state_ = EngState::Retire;
563	                return;
564	            }
565	            draw_load_step_();
566	            if (exec_inline_cmd_(draw_cmd_)) {
567	                eng_state_ = EngState::DrawLaunchWait;
568	            } else {
569	                ++draw_step_;
570	            }
571	            return;
572	
573	        case EngState::DrawLaunchWait:
574	            // tick_launch advances launch_state_; resume the walk on drain.
575	            if (launch_state_ != LaunchState::Idle)
576	                return;
577	            ++draw_step_;
578	            eng_state_ = EngState::DrawStep;
579	            return;
580	
581	        case EngState::Retire:
582	            q0_.seqnum += 1;
583	            publish_completion();
584	            ++cl_cmd_slot_;
585	            eng_state_ = EngState::Idle;
586	            return;
587	    }
588	}
589	
590	void CommandProcessor::tick() {
591	    ++cycle_counter_;
592	    if (!enabled()) return;
593	    tick_engine();
594	    tick_launch();
595	}
596	
597	} // namespace vortex
